IF LEN(@EffectiveMonth)<>7 OR TRY_CONVERT(date,@EffectiveMonth+'-01',23) IS NULL THROW 51021,'EffectiveMonth must be YYYY-MM.',1; IF NOT EXISTS (SELECT 1 FROM stg.AnswerKey WHERE EffectiveDateKey=CONVERT(int,REPLACE(@EffectiveMonth,'-','')+'01')) THROW 51022,'Reporting month is absent from the approved demo control.',1; DECLARE @Stage varchar(100)=CONCAT('Master report month: ',@EffectiveMonth); EXEC mtd.usp_LogRun @RunId=@RunId,@Stage=@Stage,@Status='Succeeded';
